edits.old:
if txt > min_txt:
   addobj '<img src = "content/pic/ui/buttons/legacy/back_button.png">'
else
   addobj '<img src = "content/pic/ui/buttons/legacy/noback_button.png">'
end
if txt < txt_count: addobj '<img src = "content/pic/ui/buttons/legacy/forward_button.png">'
$yes = {
      if sound_on = 1: play 'content\snd\kkm.wav', sound_volume
      killobj
      killvar 'bm_index'
      black_market_taken['<<s_type>>'] = 1
      sparks -= bm_price
      gs 'black_market_get_comm_slave'
      gt 'shop_general'
}
$no = {
   killvar 'bm_index'
   gt $return_lock
}
if sparks >= bm_price and txt_count <> 0: *p {<div id = "approve"><a href = 'EXEC: dynamic $yes'><img src="content/pic/ui/buttons/legacy/approve.png"></a></div>}
*p {<div id = "deny"><a href = 'EXEC: killobj & dynamic $no'><img src="content/pic/ui/buttons/legacy/deny.png"></a></div>}

